import React, { useState } from 'react';
import axios from 'axios';

function VulnScanner() {
  const [url, setUrl] = useState('');
  const [report, setReport] = useState(null);

  const scan = () => {
    axios.post('/api/vuln/scan', {url})
      .then(res => setReport(res.data))
      .catch(err => console.error(err));
  };

  return (
    <div>
      <h2>Website Vulnerability Scanner</h2>
      <div className="input-group mb-3">
        <input type="text" className="form-control" value={url} onChange={e=>setUrl(e.target.value)} placeholder="https://example.com" />
        <div className="input-group-append">
          <button className="btn btn-primary" onClick={scan}>Scan</button>
        </div>
      </div>
      {report && (
        <div>
          <h4>Results</h4>
          <pre>{JSON.stringify(report, null, 2)}</pre>
        </div>
      )}
    </div>
  );
}

export default VulnScanner;
